import{_ as t,c as a,o as r,a5 as c}from"./chunks/framework.DuCYAsAJ.js";const p=JSON.parse('{"title":"端到端与性能测试","description":"","frontmatter":{"title":"端到端与性能测试","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#10.2","branch":"main","level":1,"order":10.2,"date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"posts/projects/zfeed/10-testing-and-benchmarking/02-end-to-end-and-performance-testing.md","filePath":"posts/projects/zfeed/10-testing-and-benchmarking/02-end-to-end-and-performance-testing.md","lastUpdated":1779632679000}'),n={name:"posts/projects/zfeed/10-testing-and-benchmarking/02-end-to-end-and-performance-testing.md"};function o(l,e,i,h,b,s){return r(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="端到端与性能测试" tabindex="-1">端到端与性能测试 <a class="header-anchor" href="#端到端与性能测试" aria-label="Permalink to &quot;端到端与性能测试&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feed_bench_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feed_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_bench_test.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer_bench_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/README.md?plain=1" target="_blank" rel="noreferrer">bench/data/README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/content_ids.csv" target="_blank" rel="noreferrer">bench/data/small/content_ids.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/follow_edges.csv" target="_blank" rel="noreferrer">bench/data/small/follow_edges.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/search_terms.csv" target="_blank" rel="noreferrer">bench/data/small/search_terms.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/tokens.json" target="_blank" rel="noreferrer">bench/data/small/tokens.json</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/users.csv" target="_blank" rel="noreferrer">bench/data/small/users.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/feed-recommend.json" target="_blank" rel="noreferrer">bench/ghz/feed-recommend.json</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/like-hot-content.json" target="_blank" rel="noreferrer">bench/ghz/like-hot-content.json</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/search-contents.json" target="_blank" rel="noreferrer">bench/ghz/search-contents.json</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/config.js" target="_blank" rel="noreferrer">bench/k6/config.js</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/lib/auth.js" target="_blank" rel="noreferrer">bench/k6/lib/auth.js</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/scenarios/hot-content.js" target="_blank" rel="noreferrer">bench/k6/scenarios/hot-content.js</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/scenarios/search.js" target="_blank" rel="noreferrer">bench/k6/scenarios/search.js</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/results/README.md?plain=1" target="_blank" rel="noreferrer">bench/results/README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/bench/run.sh" target="_blank" rel="noreferrer">scripts/bench/run.sh</a></li></ul></details><p>本页描述用于大规模验证系统完整性和性能的测试策略。zfeed 测试套件不止包含单元测试和集成测试，还包括针对真实 Docker 栈的端到端（E2E）场景、通过 <code>ghz</code> 进行的 gRPC 基准测试，以及使用 <code>k6</code> 进行的 HTTP 负载测试。</p><h2 id="端到端-e2e-测试" tabindex="-1">端到端（E2E）测试 <a class="header-anchor" href="#端到端-e2e-测试" aria-label="Permalink to &quot;端到端（E2E）测试&quot;">​</a></h2><p>E2E 测试验证多个微服务和基础设施组件（Kafka、Canal、Redis、MySQL）之间的交互。这些测试通常针对完整 Docker Compose 环境执行。</p><h3 id="关键-e2e-场景" tabindex="-1">关键 E2E 场景 <a class="header-anchor" href="#关键-e2e-场景" aria-label="Permalink to &quot;关键 E2E 场景&quot;">​</a></h3><ul><li>Count Chain E2E（<code>TestCountChainE2E</code>）：验证异步计数流水线。它触发一次互动，例如点赞，验证事件被写入 Transactional Outbox、转发到 Kafka、由 <code>count-rpc</code> 通过 Canal CDC 消费，并最终反映到 <code>count_value</code> 表和 Redis 缓存中。</li><li>Recommend Hot Snapshot E2E（<code>TestRecommendHotSnapshotE2E</code>）：验证推荐 Feed 的稳定性。它确保用户请求 <code>RecommendFeed</code> 时，系统能正确使用基于 Lua 的 snapshot 逻辑 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#L1-L107" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#1-107</a>，在并发排行更新期间仍提供一致的热门内容视图。</li><li>Observability E2E（<code>TestObservabilityE2E</code>）：验证请求能跨服务边界传播 <code>x-request-id</code>，并且 Prometheus 能正确抓取指标。</li></ul><h3 id="数据流-count-chain-e2e" tabindex="-1">数据流：Count Chain E2E <a class="header-anchor" href="#数据流-count-chain-e2e" aria-label="Permalink to &quot;数据流：Count Chain E2E&quot;">​</a></h3><p>下图展示 Count Chain E2E 测试期间验证的跨服务数据流。</p><p>Count Chain 验证流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_bench_test.go#L1-L52" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_bench_test.go#1-52</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/like-hot-content.json#L1-L19" target="_blank" rel="noreferrer">bench/ghz/like-hot-content.json#1-19</a></p><h2 id="性能与负载测试" tabindex="-1">性能与负载测试 <a class="header-anchor" href="#性能与负载测试" aria-label="Permalink to &quot;性能与负载测试&quot;">​</a></h2><p>性能测试分为微基准测试（Go <code>testing.B</code>）、gRPC 服务基准测试（<code>ghz</code>）和系统级 HTTP 负载测试（<code>k6</code>）。</p><h3 id="go-微基准测试" tabindex="-1">Go 微基准测试 <a class="header-anchor" href="#go-微基准测试" aria-label="Permalink to &quot;Go 微基准测试&quot;">​</a></h3><p>内部逻辑性能通过 Go 内置基准测试工具度量。这些测试关注缓存 key 生成、序列化、查询归一化等高频操作。</p><table tabindex="0"><thead><tr><th>函数</th><th>用途</th><th>文件</th></tr></thead><tbody><tr><td><code>BenchmarkDefaultNormalizerNormalize</code></td><td>度量搜索查询清洗和分词速度。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer_bench_test.go#L7-L23" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer_bench_test.go#7-23</a></td></tr><tr><td><code>BenchmarkBuildCountValueCacheKey</code></td><td>基准测试 count 服务的 Redis key 构造。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_bench_test.go#L15-L20" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_bench_test.go#15-20</a></td></tr><tr><td><code>BenchmarkParseHotFeedLuaResult</code></td><td>度量复杂 Feed Lua 脚本返回结果的解析效率。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feed_bench_test.go#L39-L53" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feed_bench_test.go#39-53</a></td></tr><tr><td><code>BenchmarkContentItemsToFollowItems</code></td><td>基准测试将内容项转换为 Feed 项的补全流水线。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feed_bench_test.go#L16-L37" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feed_bench_test.go#16-37</a></td></tr></tbody></table><h3 id="grpc-基准测试-ghz" tabindex="-1">gRPC 基准测试（ghz） <a class="header-anchor" href="#grpc-基准测试-ghz" aria-label="Permalink to &quot;gRPC 基准测试（ghz）&quot;">​</a></h3><p><code>ghz</code> 工具用于对单个 RPC 方法进行基准测试。配置文件位于 <code>bench/ghz/</code> 中，定义并发级别、请求 payload 和目标方法。</p><ul><li>Feed Recommend：以并发 20、总计 1000 个请求测试 <code>content.FeedService.RecommendFeed</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/feed-recommend.json#L1-L17" target="_blank" rel="noreferrer">bench/ghz/feed-recommend.json#1-17</a></li><li>Like Hot Content：测试 <code>interaction.LikeService.Like</code> 的写路径 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/like-hot-content.json#L1-L19" target="_blank" rel="noreferrer">bench/ghz/like-hot-content.json#1-19</a></li></ul><h3 id="http-负载测试-k6" tabindex="-1">HTTP 负载测试（k6） <a class="header-anchor" href="#http-负载测试-k6" aria-label="Permalink to &quot;HTTP 负载测试（k6）&quot;">​</a></h3><p><code>k6</code> 用于模拟真实用户行为的高层场景。这些测试以 <code>front-api</code> 网关为目标。</p><ul><li>场景：</li><li>Hot Content：高并发访问推荐 Feed 和热门内容详情 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/scenarios/hot-content.js" target="_blank" rel="noreferrer">bench/k6/scenarios/hot-content.js</a></li><li>Search：使用 <code>search_terms.csv</code> 中的各种词语模拟用户搜索内容和资料 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/scenarios/search.js" target="_blank" rel="noreferrer">bench/k6/scenarios/search.js</a></li><li>Write-Heavy：模拟快速发布和社交互动。</li></ul><h2 id="基准测试数据管理" tabindex="-1">基准测试数据管理 <a class="header-anchor" href="#基准测试数据管理" aria-label="Permalink to &quot;基准测试数据管理&quot;">​</a></h2><p>为确保测试可复现且安全，<code>bench/data/</code> 目录包含用于初始化环境的合成数据。</p><h3 id="数据布局与规则" tabindex="-1">数据布局与规则 <a class="header-anchor" href="#数据布局与规则" aria-label="Permalink to &quot;数据布局与规则&quot;">​</a></h3><p>所有基准测试数据都必须使用 <code>bench_</code> 前缀，以区别于生产数据或标准开发数据 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/README.md?plain=1#L19-L25" target="_blank" rel="noreferrer">bench/data/README.md#19-25</a></p><ul><li><code>users.csv</code>：包含合成用户资料，例如 <code>bench_user_10001</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/users.csv#L1-L8" target="_blank" rel="noreferrer">bench/data/small/users.csv#1-8</a></li><li><code>content_ids.csv</code>：用于互动测试的预定义内容 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/content_ids.csv#L1-L6" target="_blank" rel="noreferrer">bench/data/small/content_ids.csv#1-6</a></li><li><code>search_terms.csv</code>：常见和边界搜索查询 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/search_terms.csv#L1-L6" target="_blank" rel="noreferrer">bench/data/small/search_terms.csv#1-6</a></li><li><code>tokens.json</code>：session token 的占位文件。真实 token 应该在测试运行的 setup 阶段生成，而不是提交到仓库 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/tokens.json#L1-L4" target="_blank" rel="noreferrer">bench/data/small/tokens.json#1-4</a></li></ul><h3 id="基准测试架构" tabindex="-1">基准测试架构 <a class="header-anchor" href="#基准测试架构" aria-label="Permalink to &quot;基准测试架构&quot;">​</a></h3><p>下图展示基准测试工具如何与系统组件交互。</p><p>基准测试工具与实体图</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/README.md?plain=1#L1-L25" target="_blank" rel="noreferrer">bench/data/README.md#1-25</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/feed-recommend.json#L1-L17" target="_blank" rel="noreferrer">bench/ghz/feed-recommend.json#1-17</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer_bench_test.go#L1-L24" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer_bench_test.go#1-24</a></p><h2 id="执行与归档" tabindex="-1">执行与归档 <a class="header-anchor" href="#执行与归档" aria-label="Permalink to &quot;执行与归档&quot;">​</a></h2><p>基准测试通过 <code>scripts/bench/run.sh</code> 脚本执行，该脚本编排环境准备、数据初始化和工具运行。</p><ol><li>环境准备：确保 Docker 栈已运行且健康。</li><li>数据初始化：将 <code>bench/data/small/*.csv</code> 加载到 MySQL 数据库中。</li><li>执行：运行 <code>k6</code>、<code>ghz</code> 或 <code>go test -bench</code>。</li><li>归档：结果（延迟分位数、吞吐量、错误率）会保存到 <code>bench/results/</code>，用于历史对比 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/results/README.md?plain=1" target="_blank" rel="noreferrer">bench/results/README.md</a></li></ol><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/bench/run.sh" target="_blank" rel="noreferrer">scripts/bench/run.sh</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/README.md?plain=1#L17-L18" target="_blank" rel="noreferrer">bench/data/README.md#17-18</a></p>',35)])])}const f=t(n,[["render",o]]);export{p as __pageData,f as default};
